{"content":"#!/usr/bin/env python3
"""Live-verify every model in the table. Returns JSON dict model->status."""
import json, urllib.request, urllib.error, time, os

KEYS = {}
for line in open('/opt/data/.env'):
    line = line.strip()
    if '=' in line and not line.startswith('#'):
        k, v = line.split('=', 1); KEYS[k] = v.strip()

# Nous OAuth token from cache
nous = json.load(open('/opt/data/shared/nous_auth.json'))
NOUS_TOKEN=nous.g...en', '')
NOUS_URL = nous.get('inference_base_url', '').rstrip('/') or 'https://inference-api.nousresearch.com/v1'

def probe(url, key, model, timeout=20):
    payload = {'model': model, 'messages': [{'role': 'user', 'content': 'Reply OK'}],
               'max_tokens': 3, 'temperature': 0}
    req = urllib.request.Request(url + '/chat/completions',
                                 data=json.dumps(payload).encode(),
                                 headers={'Authorization': f'Bearer {key}',
                                          'Content-Type': 'application/json'})
    t0 = time.time()
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            json.loads(r.read().decode())
        return 'OK', round(time.time() - t0, 1)
    except urllib.error.HTTPError as e:
        return f'HTTP {e.code}', round(time.time() - t0, 1)
    except Exception as e:
        return str(e)[:35], round(time.time() - t0, 1)

results = {}

# Nous Portal
for m in ['tencent/hy3:free', 'tencent/hy3.1:free', 'deepseek/deepseek-v3.2:free', 'minimax/minimax-m2:free']:
    results[('Nous Portal', m)] = probe(NOUS_URL, NOUS_TOKEN, m)

# OpenRouter
OR_URL = 'https://openrouter.ai/api/v1'
for m in ['nvidia/nemotron-3-super-120b-a12b:free','nvidia/nemotron-3-ultra-550b-a55b:free',
          'nvidia/nemotron-3-nano-30b-a3b:free','nvidia/nemotron-3-nano-omni-30b-a3b-reasoning:free',
          'openai/gpt-oss-20b:free','google/gemma-4-26b-a4b-it:free','google/gemma-4-31b-it:free',
          'poolside/laguna-s-2.1:free','poolside/laguna-xs-2.1:free','cohere/north-mini-code:free',
          'inclusionai/ling-3.0-tiny:free','nvidia/nemotron-3.5-content-safety:free',
          'nvidia/nemotron-nano-12b-v2:free','nvidia/nemotron-nano-9b-v2:free','nvidia/nemotron-nano-12b-v2-vl:free']:
    results[('OpenRouter', m)] = probe(OR_URL, KEYS['OPENROUTER_API_KEY'], m)

# NVIDIA NIM
NV_URL = 'https://integrate.api.nvidia.com/v1'
for m in ['meta/llama-3.1-8b-instruct','meta/llama-3.1-70b-instruct','meta/llama-3.3-70b-instruct']:
    results[('NVIDIA NIM', m)] = probe(NV_URL, KEYS['NVIDIA_API_KEY'], m)

# Gemini (paid) - use key if present
GEM = KEYS.get('GEMINI_API_KEY', '')
if GEM:
    G_URL = 'https://generativelanguage.googleapis.com/v1beta/openai'
    for m in ['gemini-2.5-flash','gemini-2.5-pro','gemini-2.0-flash','gemini-1.5-pro','gemini-1.5-flash','gemini-2.5-flash-lite']:
        results[('Gemini (Paid)', m)] = probe(G_URL, GEM, m)
else:
    for m in ['gemini-2.5-flash','gemini-2.5-pro','gemini-2.0-flash','gemini-1.5-pro','gemini-1.5-flash','gemini-2.5-flash-lite']:
        results[('Gemini (Paid)', m)] = ('NO_KEY', 0)

# DeepSeek (paid) - OpenRouter paid path
for m in ['deepseek/deepseek-v4-flash','deepseek/deepseek-v4-pro']:
    results[('DeepSeek (Paid)', m)] = probe(OR_URL, KEYS['OPENROUTER_API_KEY'], m)

json.dump({f'{p}||{m}': {'status': s, 'lat': l} for (p, m), (s, l) in results.items()},
          open('/opt/data/model/verify_results.json', 'w'), indent=2)

# Print summary
for (p, m), (s, l) in results.items():
    print(f'  {s:12s} {l:4}s  {p:14s} {m}')
